namespace ArgentSea.Orleans;
public sealed class OrleansQueryNotProvidedException : Exception {   // derives from System.Exception
  OrleansQueryNotProvidedException([CallerMemberName] string callerMethod = "");
      // "The current Orleans Grain does not have a query defined for its {callerMethod.Replace("StateAsync", "")} method."
  OrleansQueryNotProvidedException(string grainType, [CallerMemberName] string callerMethod = "");
      // "The Orleans Grain “{grainType}” does not have a query defined for its {callerMethod.Replace("StateAsync", "")} method."
  OrleansQueryNotProvidedException(string grainType, Exception innerException, [CallerMemberName] string callerMethod = "");
}
// There is no free-form message constructor: a single string argument is the GRAIN TYPE, and a second string is the operation name. When callerMethod is omitted the compiler supplies the calling member's name. The "StateAsync" suffix is stripped, so ReadStateAsync/WriteStateAsync/ClearStateAsync render as Read/Write/Clear, while a query-definition accessor name (ReadQuery, WriteQuery, ClearQuery) is kept as is.
// Carries no properties beyond the message. Raised when a grain type has no query registered for the requested persistence operation, or a query-definition role was never supplied; it is a configuration defect, not a transient fault, and callers should fix the grain's query registration.
